<!DOCTYPE html>
<html lang="id">

<head>
    <meta charset="utf-8" />
    <style>
    @page {
        size: 85.6mm 53.98mm landscape;
        margin: 0;
    }

    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }

    body {
        background: #fff;
    }

    /* CR80 landscape: 85.6mm x 53.98mm */
    .card {
        width: 85.6mm;
        height: 53.98mm;
        position: relative;
        overflow: hidden;
        page-break-after: always;
    }

    /* Background gambar polosan mengisi seluruh kartu */
    .card-bg {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
    }

    /* ─── DEPAN: posisi elemen di atas background ─── */

    /* Foto anggota */
    .photo-box {
        position: absolute;
        top: 27.5mm;
        right: 3mm;
        width: 14mm;
        height: 18mm;
        overflow: hidden;
        background: #ddd;
    }

    .photo-box img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: top center;
    }

    /* QR Code */


    .qr-box img {
        width: 100%;
        height: 100%;
    }

    /* Nama anggota */
    .member-name {
        position: absolute;
        bottom: 14mm;
        left: 20mm;
        right: 19mm;
        font-family: Arial, sans-serif;
        font-size: 7pt;
        font-weight: 900;
        color: #1A2A3A;
        letter-spacing: 0.02em;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    /* NIA */
    .member-nia {
        position: absolute;
        bottom: 10.5mm;
        left: 20mm;
        right: 19mm;
        font-family: Arial, sans-serif;
        font-size: 5.5pt;
        font-weight: 700;
        color: #1A2A3A;
    }

    /* Berlaku sampai */
    .member-valid {
        position: absolute;
        bottom: 4mm;
        left: 20mm;
        right: 19mm;
        font-family: Arial, sans-serif;
        font-size: 5pt;
        font-weight: 700;
        color: #1A2A3A;
        background: rgba(255, 255, 255, 0.6);
        padding: 0.5mm 1mm;
        display: inline-block;
    }
    </style>
</head>

<body>

    {{-- ════ SISI DEPAN ════ --}}
    <div class="card">
        <img class="card-bg"
            src="data:image/png;base64," />

        {{-- Foto --}}
        <div class="photo-box">
            @if ($member->photo && file_exists(storage_path('app/public/' . $member->photo)))
            <img src="{{ storage_path('app/public/' . $member->photo) }}" />
            @endif
        </div>

        {{-- QR Code --}}
        <div class="qr-box">
            <img src="{{ $qrPath }}" />
        </div>

        {{-- Nama --}}
        <div class="member-name">{{ strtoupper($member->full_name) }}</div>

        {{-- NIA --}}
        <div class="member-nia">NIA. {{ $member->member_number }}</div>

        {{-- Berlaku sampai --}}
        <div class="member-valid">
            Berlaku Sampai: {{ $member->active_until
            ? $member->active_until->format('d M Y')
            : now()->addYear()->format('d M Y') }}
        </div>
    </div>

    {{-- ════ SISI BELAKANG ════ --}}
    <div class="card">
        <img class="card-bg"
            src="data:image/png;base64," />
    </div>

</body>

</html>